import test from "node:test";
import assert from "node:assert/strict";

import pkg from "../package.json";
import { VERSION } from "../src/version";

// src/version.ts is generated by `prebuild` but committed, so tsc and the tests
// can run without a build. A version bump without `npm run build` leaves it stale.
test("src/version.ts matches the version in package.json", () => {
  assert.equal(VERSION, pkg.version, "run 'npm run build' (or node scripts/gen-version.cjs) and commit src/version.ts");
});
